import './neon-page-header.scss';
import { NeonWidgetSlotted } from '../shared/neon-widget-slotted';
import { dynamicText, createElement, updateDynamicText, createElementIf, updateConditionalElements, dynamicAttr, updateDynamicAttribute, updateDynamicAttributeOnChildren, classNames } from '../shared/dom-manipulation';
import { tooltipOnEllipsis, TooltipOnEllipsisObserver } from '../shared/extensions/tooltip-on-ellipsis';
export class NeonPageHeader extends NeonWidgetSlotted {
    constructor() {
        super();
        this.widgetTag = 'neon-page-header';
        this.tooltipOnEllipsisObserver = new TooltipOnEllipsisObserver(this);
    }
    //Any attribute that should be watched for changes should be listed here.
    static get observedAttributes() {
        return [
            'data-heading',
            'data-subheading',
            'data-text-color',
            'data-img-src',
            'data-show-avatar',
            'data-avatar-first-name',
            'data-avatar-last-name',
            'data-avatar-background-option',
            'data-avatar-profile-picture-src',
            'data-illustration-simple',
            'data-icon-stack-icon',
            'data-icon-stack-color',
            'data-icon-stack-shape',
            'data-icon-stack-type'
        ];
    }
    //when the attributes change this will run
    attributeChanged(attrName, oldVal, newVal) {
        super.attributeChanged(attrName, oldVal, newVal);
        // attributeChanged is called when attributes listed in "static get observedAttributes()" are changed.
        switch (attrName) {
            case 'data-heading':
                updateDynamicText(this);
                break;
            case 'data-subheading':
                updateDynamicAttribute(this, 'class');
                updateConditionalElements(this);
                updateDynamicText(this);
                break;
            case 'data-text-color':
                updateDynamicAttribute(this, 'class');
                break;
            default:
            case 'data-img-src':
                updateDynamicAttributeOnChildren(this, 'data-src');
                updateConditionalElements(this);
                break;
            case 'data-show-avatar':
                updateConditionalElements(this);
                break;
            case 'data-avatar-first-name':
                console.log('data-avatar-first-name');
                updateDynamicAttributeOnChildren(this, 'data-first-name');
                updateConditionalElements(this);
                break;
            case 'data-avatar-last-name':
                console.log('data-avatar-last-name');
                updateDynamicAttributeOnChildren(this, 'data-last-name');
                updateConditionalElements(this);
                break;
            case 'data-avatar-background-option':
                updateDynamicAttributeOnChildren(this, 'data-background-option');
                updateConditionalElements(this);
                break;
            case 'data-avatar-profile-picture-src':
                updateDynamicAttributeOnChildren(this, 'data-profile-picture-src');
                updateConditionalElements(this);
                break;
            case 'data-illustration-simple':
                updateDynamicAttributeOnChildren(this, 'data-illustration');
                updateConditionalElements(this);
                break;
            case 'data-icon-stack-icon':
                updateDynamicAttributeOnChildren(this, 'data-icon');
                updateConditionalElements(this);
                break;
            case 'data-icon-stack-color':
                updateDynamicAttributeOnChildren(this, 'data-color');
                updateConditionalElements(this);
                break;
            case 'data-icon-stack-shape':
                updateDynamicAttributeOnChildren(this, 'data-shape');
                updateConditionalElements(this);
                break;
            case 'data-icon-stack-type':
                updateDynamicAttributeOnChildren(this, 'data-type');
                updateConditionalElements(this);
                break;
        }
    }
    isAvatar() {
        return this.getAttribute('data-show-avatar') === 'true' ||
            this.getAttribute('data-avatar-first-name') != null ||
            this.getAttribute('data-avatar-last-name') != null ||
            this.getAttribute('data-avatar-profile-picture-src') != null;
    }
    renderConditionalAvatar() {
        return createElementIf(() => {
            return this.isAvatar();
        }, 'div', {
            attrs: {
                class: 'neon-page-header-avatar-container neon-page-header-media-container'
            }
        }, () => {
            return createElement('neon-2_20_1-avatar', {
                attrs: {
                    class: 'neon-page-header-avatar',
                    'data-first-name': dynamicAttr(() => { return this.getAttribute('data-avatar-first-name'); }),
                    'data-last-name': dynamicAttr(() => { return this.getAttribute('data-avatar-last-name'); }),
                    'data-profile-picture-src': dynamicAttr(() => { return this.getAttribute('data-avatar-profile-picture-src'); }),
                    'data-background-option': dynamicAttr(() => { return this.getAttribute('data-avatar-background-option'); }),
                    'data-avatar-size': 'extra-large',
                    'data-avatar-size-mobile': 'small',
                    disabled: dynamicAttr(() => { return this.getAttribute('disabled'); }),
                }
            });
        });
    }
    renderConditionalIllustrationSimple() {
        return createElementIf(() => { return this.getAttribute('data-illustration-simple') != null; }, 'div', {
            attrs: {
                class: 'neon-page-header-illustration-simple-container neon-page-header-media-container'
            }
        }, () => {
            return createElement('neon-2_20_1-illustration-simple', {
                attrs: {
                    class: 'neon-page-header-illustration-simple',
                    'data-illustration': dynamicAttr(() => { return this.getAttribute('data-illustration-simple'); }),
                }
            });
        });
    }
    renderConditionalIconStack() {
        return createElementIf(() => { return this.getAttribute('data-icon-stack-icon') != null; }, 'div', {
            attrs: {
                class: 'neon-page-header-icon-stack-container neon-page-header-media-container'
            }
        }, () => {
            return createElement('neon-2_20_1-icon-stack', {
                attrs: {
                    class: 'neon-page-header-icon-stack',
                    'data-icon': dynamicAttr(() => { return this.getAttribute('data-icon-stack-icon'); }),
                    'data-color': dynamicAttr(() => { return this.getAttribute('data-icon-stack-color'); }),
                    'data-shape': dynamicAttr(() => { return this.getAttribute('data-icon-stack-shape'); }),
                    'data-type': dynamicAttr(() => { return this.getAttribute('data-icon-stack-type'); }),
                    'data-size': 'page-header'
                }
            });
        });
    }
    renderConditionalImage() {
        return createElementIf(() => { return this.getAttribute('data-img-src') != null && this.getAttribute('data-img-src') !== ''; }, 'div', {
            attrs: {
                class: 'neon-page-header-image-container neon-page-header-media-container'
            }
        }, () => {
            return createElement('neon-2_20_1-image', {
                attrs: {
                    class: 'neon-page-header-image',
                    'data-src': dynamicAttr(() => { return this.getAttribute('data-img-src'); }),
                    'data-alt': ''
                }
            });
        });
    }
    render() {
        return [
            this.renderConditionalImage(),
            this.renderConditionalIllustrationSimple(),
            this.renderConditionalIconStack(),
            this.renderConditionalAvatar(),
            createElement('div', {
                attrs: {
                    class: dynamicAttr(() => {
                        return classNames({
                            'neon-page-header': true,
                            'neon-page-header-has-subheading': this.getAttribute('data-subheading') != null,
                            'neon-page-header-text-white': this.getAttribute('data-text-color') === 'white',
                            'neon-page-header-has-left-slot': this.slotExists('page-header-left'),
                            'neon-page-header-has-right-slot': this.slotExists('page-header-right'),
                        });
                    }),
                }
            }, createElement('h1', {
                attrs: {
                    class: 'neon-page-header-heading'
                }
            }, createElement('span', {
                text: dynamicText(() => { return this.getAttribute('data-heading'); }),
                extensions: tooltipOnEllipsis,
            })), createElementIf(() => { return this.getAttribute('data-subheading') != null; }, 'p', {
                text: dynamicText(() => { return this.getAttribute('data-subheading'); }),
                attrs: {
                    class: 'neon-page-header-subheading'
                }
            }), this.getSlot('page-header-left'), this.getSlot('page-header-right'))
        ];
    }
    connectedCallback() {
        this.tooltipOnEllipsisObserver.connect();
        super.connectedCallback();
    }
    disconnectedCallback() {
        this.tooltipOnEllipsisObserver.disconnect();
    }
}
